def run_length(s: str) -> str:
    """See SPEC.md."""
    result = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        j = i + 1
        while j < n and s[j] == c:
            j += 1
        result.append(c + str(j - i))
        i = j
    return "".join(result)

